def count_up(limit):
    cur = 1
    while cur <= limit:
        yield cur
        cur += 1
print(list(count_up(3)))

class CountUp:
    def __init__(self, limit):
        self.cur = 1
        self.limit = limit
    def __iter__(self):
        return self
    def __next__(self):
        if self.cur > self.limit:
            raise StopIteration
        v = self.cur
        self.cur += 1
        return v
print(list(CountUp(3)))
